"""Specs for further open (pre-1931) English translations that fill gaps in the Library: the Sacred Books of the East volumes not yet in, the Puranas, the
Pali chronicles and commentaries, the Pahlavi books, Palmer's Qur'an and other classics. Merged into texts_archive.SPECS (see the end of that file) and built
with python3 build_texts.py --only=ids. An ident 'PG123' is Project Gutenberg #123; the rest are Internet Archive items. Sources were found by searching the
Internet Archive on 16 November 2026 and fetched on the maker's instruction to "find everything you can and get them all".

Each spec may carry lib=(title, group, when, tr, station): the Library line and the Path station for an id that is not in the Library yet. The builder
ignores it; tools kept in the project's history use it to write the Library entry. An id with no lib already has its Library entry.
"""
import re

OCR = 'Text from a scan of the printed edition, so occasional OCR errors remain.'
SBE = 'Sacred Books of the East (Oxford: Clarendon Press)'


def G(idents, by, note='', lib=None, **kw):
    d = dict(idents=idents if isinstance(idents, list) else [idents], by=by, note=note, trim_index=True, trim_front=True, split='auto')
    if lib: d['lib'] = lib
    d.update(kw)
    return d


def vols(prefix, n):
    return ['%s %d' % (prefix, i + 1) for i in range(n)]


